CREATE TABLE "proc_policies" ("company_id" TEXT PRIMARY KEY,"commitment_timing" TEXT NOT NULL,"version" INTEGER NOT NULL,"effective_from" DATE NOT NULL,"request_hash" TEXT NOT NULL,CHECK ("commitment_timing"='ON_PO_APPROVAL'));
CREATE TABLE "proc_supplier_commitments" ("id" TEXT PRIMARY KEY,"company_id" TEXT NOT NULL,"supplier_id" TEXT NOT NULL,"source_type" TEXT NOT NULL,"source_id" TEXT NOT NULL,"status" TEXT NOT NULL,"effective_date" DATE NOT NULL,"cancelled_at" TIMESTAMP(3),"cancel_reason" TEXT,"request_hash" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "proc_commitment_company_id_id_key" UNIQUE("company_id","id"),CONSTRAINT "proc_commitment_source_key" UNIQUE("company_id","source_type","source_id"));
CREATE INDEX "proc_commitment_status_idx" ON "proc_supplier_commitments"("company_id","status");
CREATE TABLE "proc_purchase_orders" ("id" TEXT PRIMARY KEY,"company_id" TEXT NOT NULL,"commitment_id" TEXT,"supplier_id" TEXT NOT NULL,"number" TEXT NOT NULL,"origin" TEXT NOT NULL,"status" TEXT NOT NULL,"request_hash" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "proc_po_company_id_id_key" UNIQUE("company_id","id"),CONSTRAINT "proc_po_number_key" UNIQUE("company_id","number"),CONSTRAINT "proc_po_commitment_fkey" FOREIGN KEY("company_id","commitment_id") REFERENCES "proc_supplier_commitments"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "proc_po_commitment_status_idx" ON "proc_purchase_orders"("company_id","commitment_id","status");
CREATE TABLE "proc_purchase_order_lines" ("id" TEXT PRIMARY KEY,"company_id" TEXT NOT NULL,"purchase_order_id" TEXT NOT NULL,"item_reference" TEXT NOT NULL,"ordered_quantity" DECIMAL(38,18) NOT NULL,"received_quantity" DECIMAL(38,18) NOT NULL,"invoiced_quantity" DECIMAL(38,18) NOT NULL,CONSTRAINT "proc_line_company_id_id_key" UNIQUE("company_id","id"),CONSTRAINT "proc_line_po_fkey" FOREIGN KEY("company_id","purchase_order_id") REFERENCES "proc_purchase_orders"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE,CHECK("ordered_quantity">0),CHECK("received_quantity">=0 AND "received_quantity"<="ordered_quantity"),CHECK("invoiced_quantity">=0 AND "invoiced_quantity"<="received_quantity"));
CREATE INDEX "proc_line_po_idx" ON "proc_purchase_order_lines"("company_id","purchase_order_id");
CREATE TABLE "proc_commitment_history" ("id" TEXT PRIMARY KEY,"company_id" TEXT NOT NULL,"aggregate_id" TEXT NOT NULL,"kind" TEXT NOT NULL,"source_reference" TEXT,"created_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "proc_ch_company_id_id_key" UNIQUE("company_id","id"));
CREATE INDEX "proc_ch_aggregate_idx" ON "proc_commitment_history"("company_id","aggregate_id","created_at");
CREATE TABLE "proc_po_history" ("id" TEXT PRIMARY KEY,"company_id" TEXT NOT NULL,"aggregate_id" TEXT NOT NULL,"kind" TEXT NOT NULL,"source_reference" TEXT,"request_hash" TEXT,"created_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "proc_ph_company_id_id_key" UNIQUE("company_id","id"));
CREATE INDEX "proc_ph_aggregate_idx" ON "proc_po_history"("company_id","aggregate_id","created_at");
CREATE TABLE "proc_invoice_conversions" ("id" TEXT PRIMARY KEY,"company_id" TEXT NOT NULL,"purchase_order_id" TEXT NOT NULL,"line_id" TEXT NOT NULL,"billing_invoice_id" TEXT NOT NULL,"quantity" DECIMAL(38,18) NOT NULL,"reopened_quantity" DECIMAL(38,18) NOT NULL,"request_hash" TEXT NOT NULL,"status" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "proc_conv_company_id_id_key" UNIQUE("company_id","id"),CONSTRAINT "proc_conv_billing_line_key" UNIQUE("company_id","billing_invoice_id","line_id"),CONSTRAINT "proc_conv_po_fkey" FOREIGN KEY("company_id","purchase_order_id") REFERENCES "proc_purchase_orders"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "proc_conv_line_fkey" FOREIGN KEY("company_id","line_id") REFERENCES "proc_purchase_order_lines"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE,CHECK("quantity">0),CHECK("reopened_quantity">=0 AND "reopened_quantity"<="quantity"));
CREATE INDEX "proc_conv_po_status_idx" ON "proc_invoice_conversions"("company_id","purchase_order_id","status");
